#!/usr/bin/env python3
"""Generate Echoes Art Pass v2 runtime atlas.

This atlas is a deterministic, project-owned repaint built to follow the
Shattered Pixel Dungeon 16x16 material/contrast grammar. Third-party packs
were used only as structural reference; no third-party binary is embedded.
"""
from pathlib import Path
import base64
import hashlib

TARGET = Path("core/src/main/assets/environment/custom_tiles/echoes_surface_art_v2.png")
DATA = base64.b64decode(
    """"""
)
EXPECTED_SHA256 = "6d322102184e2968f6a543997d8a0883f75f36d66df84dcc87c814aca8fce4c9"

actual = hashlib.sha256(DATA).hexdigest()
if actual != EXPECTED_SHA256:
    raise SystemExit(f"Echoes Art v2 atlas hash mismatch: {actual}")

TARGET.parent.mkdir(parents=True, exist_ok=True)
TARGET.write_bytes(DATA)
print(f"Generated {TARGET} ({len(DATA)} bytes, sha256={actual})")
